/** No silent shape substitution: unsupported roles must be chosen explicitly. */
export const NATIVE_ICON_FALLBACKS = Object.freeze({});

function renderNode(node, prefix, stroke, rootProps, index = 0) {
  const [tag, attributes, children] = node;
  const props = {};
  for (const [key, raw] of Object.entries(attributes)) {
    let value = raw === '$stroke' ? stroke : raw;
    if (key === 'id') value = prefix + value;
    else if (typeof value === 'string') {
      value = value.replace(/url\(#([^)]*)\)/g, (_, id) => 'url(#' + prefix + id + ')');
      if ((key === 'href' || key === 'xlinkHref') && value.startsWith('#')) value = '#' + prefix + value.slice(1);
    }
    props[key] = value;
  }
  return React.createElement(tag, { ...props, key: index, ...rootProps },
    ...children.map((child, childIndex) => renderNode(child, prefix, stroke, undefined, childIndex)));
}

/** Native SVG shape with local rendering; size is the icon height except FishLogo. */
export function NativeIcon({ name, size = 16, weight = 'regular', ...props }) {
  const instanceId = React.useId();
  const entry = NATIVE_ICON_SOURCES[name];
  const node = NATIVE_ICON_DATA[entry?.key ?? name];
  if (!node) throw new Error('Unknown native icon: ' + String(name));
  const [, , width, height] = node[1].viewBox.split(/\s+/).map(Number);
  const brand = entry?.key === 'fish-logo' || name === 'fish-logo';
  const dimensions = brand ? { width: size, height: size * height / width } : { width: size * width / height, height: size };
  return renderNode(node, 'rssh-icon-' + instanceId.replace(/[^a-zA-Z0-9_-]/g, '') + '-',
    weight === 'medium' ? 1.3 : 1, { ...dimensions, 'aria-hidden': true, focusable: false, ...props });
}
